-- Learning catalog: B2C + B2B episodes (audio/video rows). Language: en (English).
-- Idempotent: ON CONFLICT DO NOTHING.
-- Run in Supabase SQL Editor if migrations are applied manually.

CREATE TABLE IF NOT EXISTS public.learning_content (
  id TEXT PRIMARY KEY,
  content_for TEXT NOT NULL,
  eq_type TEXT NOT NULL,
  domain TEXT NOT NULL,
  competency TEXT NOT NULL,
  episode_title TEXT NOT NULL,
  episode_description TEXT,
  industry TEXT,
  level TEXT,
  content_type TEXT NOT NULL,
  s3_link TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL,
  language TEXT NOT NULL DEFAULT 'en'
);

CREATE INDEX IF NOT EXISTS idx_learning_content_eq_type_domain
  ON public.learning_content (eq_type, domain, competency);
CREATE INDEX IF NOT EXISTS idx_learning_content_content_type
  ON public.learning_content (content_type);

ALTER TABLE public.learning_content ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "learning_content_select_authenticated" ON public.learning_content;
CREATE POLICY "learning_content_select_authenticated"
  ON public.learning_content FOR SELECT TO authenticated USING (true);


ON CONFLICT (id) DO NOTHING;
